async def run_instagram(func, *args, **kwargs):
    return await asyncio.wait_for(asyncio.to_thread(func, *args, **kwargs), timeout=REQUEST_TIMEOUT)

async def login_with_session_id(session_id, user_agent=None):
    client = Client()
    client.set_settings({'user_agent': user_agent or DEFAULT_UA})
    try:
        await run_instagram(client.login_by_sessionid, session_id)
        return client
    except (LoginRequired, asyncio.TimeoutError):
        return None
    except Exception:
        return None

async def fetch_user_info(client, username):
    try:
        return await run_instagram(client.user_info_by_username, username)
    except Exception:
        return None

def ask_username():
    while True:
        u = input('\x1b[1;37mEnter username to report (without @): \x1b[0m').strip().lstrip('@')
        if u:
            return u

async def get_valid_client():
    while True:
        session_id = ask_session_id()
        print('\x1b[1;37mVerifying session...\x1b[0m')
        client = await login_with_session_id(session_id)
        if client:
            print('\x1b[1;32mSession verified.\x1b[0m')
            COOKIES['sessionid'] = session_id
            return client
        print('\x1b[1;31mLogin failed. Session ID may be invalid or expired. Please re-enter.\x1b[0m')

async def get_target_user(client):
    while True:
        username = ask_username()
        print(f'\x1b[1;37mSearching @{username}...\x1b[0m')
        info = await fetch_user_info(client, username)
        if not info:
            print(f'\x1b[1;31mUser @{username} not found. Please re-enter a valid username.\x1b[0m')
            continue
        print()
        print_user_info(info)
        print()
        while True:
            ans = input('\x1b[1;37mIs this the user? (y/n): \x1b[0m').strip().lower()
            if ans in ('y', 'yes'):
                return info
            if ans in ('n', 'no'):
                break
            print('\x1b[1;31mPlease enter y or n.\x1b[0m')

def print_user_info(info):
    print(f'Username        : @{info.username}')
    print(f'User ID         : {info.pk}')
    print(f"Full Name       : {info.full_name or 'N/A'}")
    print(f"Biography       : {info.biography or 'N/A'}")
    print(f"External URL    : {info.external_url or 'N/A'}")
    print(f'Followers       : {info.follower_count}')
    print(f'Following       : {info.following_count}')
    print(f'Posts           : {info.media_count}')
    print(f"Private         : {('Yes' if info.is_private else 'No')}")
    print(f"Verified        : {('Yes' if info.is_verified else 'No')}")
    print(f"Business        : {('Yes' if info.is_business else 'No')}")
    print(f"Professional    : {getattr(info, 'account_type', 'N/A')}")
