TAGS = {'bullying_done': ' BULLYING ', 'drugs_done': ' DRUGS ', 'false info': ' FALSE INFO ', 'hate and speech': ' HATE AND SPEECH ', 'nudity-2': ' NUDITY-2 ', 'nudity': ' NUDITY ', 'scam': ' SCAM ', 'spam': ' SPAM ', 'sucide': ' SUCIDE ', 'weapons': ' WEAPONS '}
W = '\x1b[1;37m'
R = '\x1b[0m'

def fire(kind, data, session):
    tag = TAGS.get(kind, kind.upper())
    try:
        r = session.post(URL, cookies=COOKIES, headers=HEADERS, data=data, timeout=30)
        print(f'\n{W}[{tag}] : {r.status_code}{R}')
        return r
    except requests.RequestException as e:
        print(f'{W}[{tag}] : ERR {e}{R}')
        return None

def ask_session_id():
    while True:
        sid = input('\x1b[1;37mSession ID : \x1b[0m').strip()
        if sid:
            return sid

async def main_async():
    if not PAYLOADS:
        print('no payloads loaded')
        return 1
    client = await get_valid_client()
    user_info = await get_target_user(client)
    print(f'\n\x1b[1;32m[ Target Fixed ] user > [@{user_info.username}]\x1b[0m')
    print_user_info(user_info)
    print(f'\n\x1b[1;37mStarting reporting...\x1b[0m\n')
    target_id = str(user_info.pk)
    session = requests.Session()
    items = [(kind, data.replace('314216', target_id)) for kind, data in PAYLOADS.items()]
    i = 0
    try:
        while True:
            kind, data = items[i % len(items)]
            i += 1
            if i % len(items) == 1:
                random.shuffle(items)
            fire(kind, data, session)
    except KeyboardInterrupt:
        print('\nstopped')
    return 0

def main():
    try:
        return asyncio.run(main_async())
    except KeyboardInterrupt:
        print('\nstopped')
        return 0
if __name__ == '__main__':
    sys.exit(main())
